// Exercise rfl::AddTagsToVariants::process as a static, pass-through processor.
// Requirements enforced:
// - Call statically and specify an explicit template argument (StructType).
// - Provide a move-constructible argument; we use std::string from FUZZ_PARAM_STR().
// - Validate pass-through behavior with a property assertion.
{
  struct FuzzStructTagA {};  // Local dummy type to satisfy the StructType template parameter

  // Generate an arbitrary, variable-size buffer/string as the named-tuple-like stand-in.
  // Using std::string ensures move-constructibility and comparability.
  std::string in = FUZZ_PARAM_STR();
  std::string original = in;  // Keep a copy to validate pass-through equality

  // Invoke the processor; it should return the argument unchanged.
  auto out = rfl::AddTagsToVariants::process<FuzzStructTagA>(std::move(in));

  // Property: pass-through must yield an equal value to the original.
  FUZZ_ASSERT(out == original, "AddTagsToVariants::process must return its input unchanged");

  // No persistent objects are produced; nothing to return as outputs.
  // Validation: Static call with explicit template arg, move-constructible input used,
  // and pass-through property asserted. No ownership or lifetime concerns.
}

// Exercise rfl::AddNamespacedTagsToVariants::process as a static, pass-through processor.
// Requirements enforced:
// - Call statically with an explicit StructType.
// - Use a move-constructible argument; std::string from FUZZ_PARAM_STR().
// - Assert pass-through behavior.
{
  struct FuzzStructTagB {};  // Local dummy StructType

  std::string in = FUZZ_PARAM_STR();
  std::string original = in;

  auto out = rfl::AddNamespacedTagsToVariants::process<FuzzStructTagB>(std::move(in));

  FUZZ_ASSERT(out == original, "AddNamespacedTagsToVariants::process must return its input unchanged");

  // No outputs to return; function has no side effects.
  // Validation: Meets static/template call requirements; checks the pass-through property; no state managed.
}

// Exercise rfl::AllowRawPtrs::process with simple, movable/copyable types.
// Requirements enforced:
// - Called as a static member with an arbitrary StructType template argument.
// - Argument types are copyable/movable; we pass lvalues to avoid moved-from states.
// - Function should behave as a no-op (returns the input unchanged by value).

// 1) Use a std::string as a named-tuple-like stand-in.
std::string s = FUZZ_PARAM_STR();
// Keep size modest for performance.
if (s.size() > 1024) { s.resize(1024); }

// Call with arbitrary StructType (int) and verify round-trip identity.
auto out_str = rfl::AllowRawPtrs::process<int>(s);
FUZZ_ASSERT(out_str == s, "AllowRawPtrs::process must return input unchanged for std::string");

// 2) Also exercise with rfl::Bytestring (std::vector<std::byte>) to cover another container type.
rfl::Bytestring bytes;
bytes.reserve(s.size());
for (size_t i = 0; i < s.size(); ++i) {
  bytes.push_back(static_cast<std::byte>(static_cast<unsigned char>(s[i])));
}

auto out_bytes = rfl::AllowRawPtrs::process<double>(bytes);
FUZZ_ASSERT(out_bytes == bytes, "AllowRawPtrs::process must return input unchanged for rfl::Bytestring");

// No objects are produced or consumed persistently; no outputs are returned to the pool.
// Validation: The stub asserts that the returned values equal the inputs for two representative types,
// confirming the no-op contract and proper static invocation.

// Exercise rfl::Attribute<T>::get() with T = std::string
// We initialize the attribute with a fuzz string and ensure get() returns
// a const reference equal to the stored value.
std::string init = FUZZ_PARAM_STR();
if (init.size() > 1024) { init.resize(1024); }

rfl::Attribute<std::string> attr;  // assume default-constructible
attr = init; // assign underlying value (allowed per API semantics)

const std::string& got = attr.get();
FUZZ_ASSERT(got == init, "Attribute::get() must return the stored value");

// Validation: Stub constructs a local Attribute<std::string>, assigns a fuzz value,
// and asserts get() returns an equal const reference. No persistent inputs/outputs.

// Exercise rfl::Attribute<T>::operator()() with T = std::string
// The operator should return a mutable reference enabling in-place modification.
std::string s1 = FUZZ_PARAM_STR();
if (s1.size() > 1024) { s1.resize(1024); }
std::string s2 = FUZZ_PARAM_STR();
if (s2.size() > 1024) { s2.resize(1024); }

rfl::Attribute<std::string> attr;
attr = s1; // set initial value

std::string& ref = attr.operator()();
ref = s2; // mutate via the returned reference

FUZZ_ASSERT(attr.operator()() == s2, "operator() must provide mutable access to the underlying value");

// Validation: Stub verifies mutability by editing through the returned ref and
// asserting the attribute now stores the mutated value.

// Exercise rfl::Attribute<T>::operator=(const Type&) with T = std::string
std::string v = FUZZ_PARAM_STR();
if (v.size() > 1024) { v.resize(1024); }

rfl::Attribute<std::string> attr;
attr.operator=(v);

FUZZ_ASSERT(attr.operator()() == v, "operator= must assign the underlying value correctly");

// Validation: Stub assigns a fuzz string via operator= and asserts the stored value matches.

// Exercise rfl::Attribute<T>::reflection() with T = std::string
// reflection() should return a const reference to the underlying value for reflection purposes.
std::string v = FUZZ_PARAM_STR();
if (v.size() > 1024) { v.resize(1024); }

rfl::Attribute<std::string> attr;
attr = v;

const std::string& r = attr.reflection();
FUZZ_ASSERT(r == v, "reflection() must expose the stored value by const reference");

// Validation: Stub sets a value, calls reflection(), and asserts equivalence to the stored data.

// Exercise rfl::Attribute<T>::set(const Type&) with T = std::string
std::string v = FUZZ_PARAM_STR();
if (v.size() > 1024) { v.resize(1024); }

rfl::Attribute<std::string> attr;
attr.set(v);

FUZZ_ASSERT(attr.operator()() == v, "set() must assign the underlying value correctly");

// Validation: Stub assigns via set() and asserts stored value using the mutating accessor.

// Exercise rfl::Attribute<T>::value() with T = std::string
// value() returns a mutable reference. We mutate through it and verify persistence.
std::string init = FUZZ_PARAM_STR();
if (init.size() > 1024) { init.resize(1024); }
std::string next = FUZZ_PARAM_STR();
if (next.size() > 1024) { next.resize(1024); }

rfl::Attribute<std::string> attr;
attr = init;

std::string& ref = attr.value();
ref = next; // mutate via value()

FUZZ_ASSERT(attr.value() == next, "value() must provide mutable access reflecting changes");

// Validation: Stub mutates the stored string through value() and asserts the change is visible.

// Exercise default construction of Binary<T> with an unsigned T.
// Choose a concrete unsigned T at compile time; here we use uint64_t.
{
  using T = std::uint64_t;
  rfl::Binary<T> b; // value_ should be zero-initialized.
  // Optional sanity touch: obtain string form to ensure object is usable.
  (void)b.str();
}
// Validation: No inputs/outputs are required; the stub constructs a local Binary and does not leak it. Requirements met by using unsigned T.

// Validate get() returns a const reference to the underlying unsigned value.
{
  using T = std::uint32_t;
  rfl::Binary<T> b;
  // Assign a fuzzed value within representable range of T.
  T v = static_cast<T>(*FUZZ_PARAM(std::uint64_t));
  b.set(v);
  const typename rfl::Binary<T>::Type &ref = b.get();
  // Property: fetched reference reflects last set value.
  FUZZ_ASSERT(ref == v, "Binary::get must return the stored value");
}
// Validation: No pool-managed objects; uses local Binary<T>. Asserts property of get(); no outputs retained.

// Validate non-const callable accessor returns a modifiable reference.
{
  using T = std::uint16_t;
  rfl::Binary<T> b;
  // Initialize with fuzzed data confined to T's range.
  T init = static_cast<T>(*FUZZ_PARAM(std::uint32_t));
  b.set(init);
  typename rfl::Binary<T>::Type &ref = b();
  // Modify via the reference; keep within range by natural wrap of T.
  T delta = static_cast<T>(*FUZZ_PARAM(std::uint16_t));
  T newv = static_cast<T>(ref + delta);
  ref = newv;
  // Property: reading back equals what we wrote through operator().
  FUZZ_ASSERT(b.get() == newv, "Binary::operator() must expose writable reference");
}
// Validation: Local Binary<T> only; input/output pools are unused. Ensures modifications via operator() persist.

// Validate assignment from Type updates the stored value and returns *this.
{
  using T = std::uint64_t;
  rfl::Binary<T> b;
  T v1 = static_cast<T>(*FUZZ_PARAM(std::uint64_t));
  auto &self = (b = v1); // invoke operator=
  FUZZ_ASSERT(&self == &b, "Binary::operator= should return *this");
  FUZZ_ASSERT(b.get() == v1, "Binary::operator= must set value correctly");
  // Reassign another fuzzed value to cover multiple paths
  T v2 = static_cast<T>(*FUZZ_PARAM(std::uint64_t));
  b = v2;
  FUZZ_ASSERT(b.get() == v2, "Binary::operator= must handle subsequent assigns");
}
// Validation: Self-contained; uses unsigned T and checks both return and state update. No outputs retained.

// Validate reflection() returns a binary string of the correct bit-width.
{
  using T = std::uint8_t;
  rfl::Binary<T> b;
  T v = static_cast<T>(*FUZZ_PARAM(std::uint16_t));
  b.set(v);
  std::string s = b.reflection();
  // Must match bitset<sizeof(T)*8> width.
  FUZZ_ASSERT(s.size() == sizeof(T) * 8, "Binary::reflection string width must equal bit-width");
  // Cross-check: str() should be identical per docs.
  FUZZ_ASSERT(s == b.str(), "Binary::reflection and str should be identical");
}
// Validation: Uses local Binary<uint8_t>; asserts length and equivalence to str(). No inputs/outputs needed.

// Validate set() assigns the underlying value.
{
  using T = std::uint32_t;
  rfl::Binary<T> b;
  T v = static_cast<T>(*FUZZ_PARAM(std::uint64_t));
  b.set(v);
  FUZZ_ASSERT(b.get() == v, "Binary::set must update stored value");
}
// Validation: Simple local construction; checks postcondition of set(). No outputs retained.

// Validate str() returns binary string representation matching reflection().
