// Fuzzer stub for rfl::from_generic
// Strategy: instantiate a single safe template specialization to avoid
// compile-time duplication/name conflicts seen with variant/tag processors.
// We choose T = bool (primitive), with no additional policy parameters.
// We do not assert success of the conversion since errors are valid outcomes.

// Ensure non-null input (runtime guarantees this, but assert for property tracking).
FUZZ_ASSERT(g != nullptr, "rfl::from_generic: input Generic pointer must be non-null");

// Exercise the API. This should route to a simple "to_bool" style conversion path.
// Discard the result; it may be a T or a Result-like wrapper depending on implementation.
{ auto result = rfl::from_generic<bool>(*g); (void)result; }

// No outputs to return; ownership remains with the fuzzer runtime.

// We exercise rfl::make_from_tuple by using an empty rfl::Tuple<> and a T that is
// default-constructible from zero arguments. rfl::Generic meets this requirement.
// - This avoids relying on undocumented constructors for rfl::Tuple<Ts...>.
// - The tuple argument is a local ephemeral; the returned T is made persistent by
//   allocating it on the heap and exposing it as an output object.

// 1) Create the empty tuple input (const lvalue reference compatible)
rfl::Tuple<> tup;

// 2) Construct T from the tuple via make_from_tuple (should default-construct Generic)
auto value = rfl::make_from_tuple<rfl::Generic>(tup);

// 3) Persist the result for the fuzzer object pool
rfl::Generic *generic = new rfl::Generic(std::move(value));

// 4) Sanity-touch the API surface to ensure the object is usable and to increase coverage
//    We do not assert properties about null-ness because rfl::Generic default semantics
//    are library-defined; we only exercise accessors safely.
(void)generic->get();
(void)generic->variant();
(void)generic->reflection();

// 5) Mark provenance for downstream stubs (if any)
FUZZ_SET_ATTR_INT(generic, "constructed_from_tuple", 1);
// generic is provided as an output

// Build an rfl::Generic input from simple, supported primitive alternatives only.
// This avoids exercising parser machinery that expects named-tuple/struct fields.
unsigned int sel = *FUZZ_PARAM(unsigned int) % 5; // 0: bool, 1: int64, 2: double, 3: string, 4: null

rfl::Generic gin; // input generic value
switch (sel) {
  case 0: {
    bool v = ((*FUZZ_PARAM(unsigned int)) & 1) != 0;
    gin = rfl::Generic(v);
    break;
  }
  case 1: {
    int64_t v = static_cast<int64_t>(*FUZZ_PARAM(unsigned int));
    gin = rfl::Generic(v);
    break;
  }
  case 2: {
    double v = static_cast<double>(*FUZZ_PARAM(unsigned int)) / 17.0;
    gin = rfl::Generic(v);
    break;
  }
  case 3: {
    std::string s = FUZZ_PARAM_STR();
    // Keep strings modest to avoid large allocations; truncate if needed.
    if (s.size() > 512) s.resize(512);
    gin = rfl::Generic(s);
    break;
  }
  default: {
    // Explicit null value
    gin = rfl::Generic(std::nullopt);
    break;
  }
}

// Convert Generic to Generic via rfl::to_generic; this should be a pass-through
// without requiring struct field reflection, keeping compilation paths simple.
rfl::Generic gout = rfl::to_generic(gin);

// Persist the result as an output owned by the fuzzer runtime.
rfl::Generic *generic = new rfl::Generic(std::move(gout));

// Validation: output is non-null and inputs satisfied the requirement of a valid const-ref argument.

// Construct a standalone rfl::Generic::Object (i.e., rfl::Object<rfl::Generic>)
// Populate it with a small set of key/value pairs to ensure it is usable by
// downstream stubs exercising iteration and lookup APIs.

// 1) Allocate the object on the heap so the fuzzer runtime can manage it.
rfl::Generic::Object *obj = new rfl::Generic::Object();
if (!obj) { FUZZ_BAIL(); }

// 2) Build a small vector of elements to insert, keeping sizes modest for perf.
using Pair = std::pair<std::string, rfl::Generic>;
std::vector<Pair> elems;
unsigned int n = (*FUZZ_PARAM(unsigned int) % 6u); // up to 5 elements
// Always insert at least one element to avoid empty-only paths
if (n == 0u) { n = 1u; }

elems.reserve(n);
for (unsigned int i = 0; i < n; ++i) {
  std::string key = FUZZ_PARAM_STR();
  if (key.size() > 64) key.resize(64);
  // Mix simple alternatives for rfl::Generic payloads
  unsigned int sel = *FUZZ_PARAM(unsigned int) % 5u;
  rfl::Generic val;
  if (sel == 0u) {
    val = static_cast<bool>((*FUZZ_PARAM(unsigned int)) & 1u);
  } else if (sel == 1u) {
    val = static_cast<int64_t>(*FUZZ_PARAM(int));
  } else if (sel == 2u) {
    val = static_cast<double>(*FUZZ_PARAM(int)) / 13.0;
  } else if (sel == 3u) {
    std::string s = FUZZ_PARAM_STR();
    if (s.size() > 128) s.resize(128);
    val = s;
  } else {
    val = std::nullopt; // explicit null
  }
  elems.emplace_back(std::move(key), std::move(val));
}

// 3) Insert the range in one go; this appends all elements. Duplicates are allowed.
obj->insert_range(elems.begin(), elems.end());

// 4) Exercise operator[] to ensure default-insertion path is covered too.
{
  std::string k = FUZZ_PARAM_STR();
  if (k.size() > 32) k.resize(32);
  rfl::Generic &ref = (*obj)[k];
  (void)ref; // do not modify further to avoid iterator invalidation surprises in callers
}

// 5) Validate basic container invariants.
FUZZ_ASSERT(obj->max_size() > 0, "rfl::Object must report positive max_size");
FUZZ_ASSERT(obj->size() >= elems.size(), "size() should be at least number of inserted elements");

// 6) Hand the populated object to the fuzzer runtime.
